  function rng(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
  function audio(t) {
    const beat = t * 124 / 60, ph = beat % 1, kick = Math.exp(-ph * 7);
    const s16 = (beat * 4) % 1, hat = Math.exp(-s16 * 12) * (Math.floor(beat * 4) % 2 ? 1 : 0.35);
    const bands = [];
    for (let i = 0; i < 32; i++) {
      const low = 1 - i / 32;
      let b = 0.3 + 0.22 * Math.sin(t * (1.1 + i * 0.31) + i * 2.1) + 0.15 * Math.sin(t * (3.3 + i * 0.17) + i);
      b += kick * low * 0.6 + hat * (1 - low) * 0.4;
      bands.push(Math.max(0.02, Math.min(1, b)));
    }
    return { kick, hat, bands, beat };
  }

  const SHARDS = (() => {
    const r = rng(7), out = [];
    for (let i = 0; i < 20; i++) {
      const n = 3 + Math.floor(r() * 3), pts = [], s = 0.08 + r() * 0.2;
      for (let k = 0; k < n; k++) { const g = k / n * Math.PI * 2 + r() * 0.6; pts.push([Math.cos(g) * s * (0.4 + r()), Math.sin(g) * s * (0.4 + r())]); }
      out.push({ cx: r(), cy: r(), pts, sp: (r() - 0.5) * 0.5, dark: r() < 0.45 });
    }
    return out;
  })();

